import {emptyState} from './components.js';
import {checkoutItems,summaryHTML} from './checkout.js';
function contents(products,cart){const items=checkoutItems(products,cart);return items.length?`<div class="cart-review-list">${summaryHTML(items)}</div><div class="cart-review-actions"><a class="checkout-continue" href="/catalog">Продолжить покупки</a><a class="button cart-next" href="/checkout">Перейти к заказу</a></div>`:emptyState('В корзине пока пусто','Добавьте понравившиеся очки из каталога.');}
export function cartPageHTML(products,cart=[]){return `<section class="checkout-page checkout-classic cart-review wrap"><header class="checkout-heading"><h1>Корзина</h1><p>Проверьте выбранные очки и количество перед оформлением заказа.</p></header><div id="cart-review-content">${contents(products,cart)}</div></section>`;}
export function mountCart(root,products,store){const content=root.querySelector('#cart-review-content');let active=true;const refresh=()=>{if(active)content.innerHTML=contents(products,store.getCart());};const change=event=>{const id=event.target.dataset.orderQuantity;if(id)store.setQuantity(id,event.target.value);};const click=event=>{const button=event.target.closest('[data-order-remove]');if(button)store.removeFromCart(button.dataset.orderRemove);};content.addEventListener('change',change);content.addEventListener('click',click);return{refresh,dispose(){active=false;content.removeEventListener('change',change);content.removeEventListener('click',click);}};}

